                "language": "python",
                "code": "from typing import List, Dict, Tuple\nfrom pydantic import BaseModel, Field, computed_field\nimport math\n\nclass DraftTokenCandidate(BaseModel):\n    token_id: int\n    token_str: str\n    draft_prob: float = Field(ge=0.0, le=1.0)\n    target_prob: float = Field(ge=0.0, le=1.0)\n    accepted: bool = False\n\nclass SpeculativeIteration(BaseModel):\n    iteration_index: int\n    speculative_window_k: int = 5\n    candidates: List[DraftTokenCandidate]\n    emitted_token_count: int = 0\n    forward_pass_latency_ms: float\n\n    @computed_field\n    @property\n    def acceptance_rate_pct(self) -> float:\n        if not self.candidates:\n            return 0.0\n        accepted_count = sum(1 for c in self.candidates if c.accepted)\n        return round((accepted_count / len(self.candidates)) * 100.0, 2)\n\n    @computed_field\n    @property\n    def effective_per_token_latency_ms(self) -> float:\n        if self.emitted_token_count == 0:\n            return self.forward_pass_latency_ms\n        return round(self.forward_pass_latency_ms / self.emitted_token_count, 2)\n\nclass SpeculativeVerificationKernel:\n    \"\"\"Simulates enterprise GPU speculative decoding verification and tree rejection sampling.\"\"\"\n    def __init__(self, target_base_latency_ms: float = 32.0, draft_base_latency_ms: float = 4.5):\n        self.target_latency = target_base_latency_ms\n        self.draft_latency = draft_base_latency_ms\n\n    def verify_tokens(\n        self, \n        draft_tokens: List[Tuple[str, float]], \n        target_probs: List[float]\n    ) -> SpeculativeIteration:\n        candidates = []\n        emitted = 0\n        # Draft generation overhead\n        total_latency = (len(draft_tokens) * self.draft_latency) + self.target_latency\n\n        for i, ((tok, q_val), p_val) in enumerate(zip(draft_tokens, target_probs)):\n            accept_prob = min(1.0, p_val / max(1e-5, q_val))\n            # reliable threshold for simulation\n            is_accepted = accept_prob >= 0.75\n            candidates.append(DraftTokenCandidate(\n                token_id=i,\n                token_str=tok,\n                draft_prob=q_val,\n                target_prob=p_val,\n                accepted=is_accepted\n            ))\n            if is_accepted:\n                emitted += 1\n            else:\n                # Rejection triggers 1 replacement token from target and halts iteration\n                emitted += 1\n                break\n\n        return SpeculativeIteration(\n            iteration_index=1,\n            speculative_window_k=len(draft_tokens),\n            candidates=candidates,\n            emitted_token_count=emitted,\n            forward_pass_latency_ms=round(total_latency, 2)\n        )\n"
